formal.sparql:
# CQ-1: Which active sessions were established from an authentication
# journey execution below AAL2, and for which principals?
PREFIX core:    <https://w3id.org/examplebank/platform/core#>
PREFIX authn:   <https://w3id.org/examplebank/platform/authn#>
PREFIX session: <https://w3id.org/examplebank/platform/session#>

SELECT ?session ?principal ?aal WHERE {
    ?session a session:Session ;
             session:hasState session:state-active ;
             session:boundToPrincipal ?principal ;
             session:establishedBy ?x .
    ?x authn:achievedAssuranceLevel ?aal .
    ?aal authn:assuranceRank ?rank .
    FILTER (?rank < 2)
}

# CQ-2: For every route, which upstream does it reach and which policy
# enforcement point mediates it?
PREFIX core:    <https://w3id.org/examplebank/platform/core#>
PREFIX ingress: <https://w3id.org/examplebank/platform/ingress#>

SELECT ?route ?upstream ?pep WHERE {
    ?route a ingress:Route ;
           ingress:routesTo ?upstream .
    OPTIONAL { ?route core:enforcedBy ?pep }
}

# CQ-3: Who executed and who approved each policy change, and was any
# approver human?
PREFIX core: <https://w3id.org/examplebank/platform/core#>
PREFIX cp:   <https://w3id.org/examplebank/platform/control-plane#>

SELECT ?change ?executor ?approver ?humanApproved WHERE {
    ?change a cp:PolicyChangeEvent ;
            cp:executedBy ?executor ;
            cp:hasApproval ?a .
    ?a cp:approvedBy ?approver .
    BIND (EXISTS { ?approver a core:HumanPrincipal } AS ?humanApproved)
}

# CQ-4: Which attribute assertions back decisions about a principal, and
# which authoritative source issued each?
PREFIX authz: <https://w3id.org/examplebank/platform/authz#>

SELECT ?principal ?attrName ?attrValue ?issuer WHERE {
    ?assertion a authz:AttributeAssertion ;
               authz:aboutPrincipal ?principal ;
               authz:attributeName ?attrName ;
               authz:attributeValue ?attrValue ;
               authz:assertedBy ?issuer .
}

# CQ-5: For each Permit decision, trace the full assurance chain:
# decision -> session -> journey execution -> comprised events' methods
# and the execution's achieved AAL. This is the audit answer to "why did
# the platform believe this access was authorized?"
PREFIX core:    <https://w3id.org/examplebank/platform/core#>
PREFIX authn:   <https://w3id.org/examplebank/platform/authn#>
PREFIX session: <https://w3id.org/examplebank/platform/session#>
PREFIX authz:   <https://w3id.org/examplebank/platform/authz#>

SELECT ?decision ?principal ?policy ?method ?aal WHERE {
    ?decision a authz:PolicyDecision ;
              authz:decisionOutcome authz:outcome-permit ;
              authz:requestingPrincipal ?principal ;
              authz:evaluatedPolicy ?policy ;
              authz:withinSession ?s .
    ?s session:establishedBy ?x .
    ?x authn:comprisesEvent ?e ;
       authn:achievedAssuranceLevel ?aal .
    ?e authn:usedMethod ?method .
}

# CQ-6: Which workload principals exist, what are their SPIFFE identities,
# and which changes have they executed?
PREFIX core: <https://w3id.org/examplebank/platform/core#>
PREFIX cp:   <https://w3id.org/examplebank/platform/control-plane#>

SELECT ?workload ?spiffeId ?change WHERE {
    ?workload a core:WorkloadPrincipal ;
              core:identifier ?spiffeId .
    OPTIONAL { ?change cp:executedBy ?workload }
}

# CQ-7: Does this subject's tenant have the right to enter this application
# through this platform-controlled endpoint and deployment scope?
#
# The platform PDP's question. Every join is a governed fact:
#   principal -> tenant        active, human-approved membership
#   tenant    -> endpoint      route binding, behind an approved declaration
#   endpoint  -> application   the route serves it
#   tenant    -> application   ownership
#   application -> scope       a current enablement covers it
#   tenant    -> capability    active subscription for each confirmed requirement
#   capability -> scope        an offering covers the enablement scope
#
# What this deliberately does NOT answer is what the subject may then do
# inside the application: that is the application PDP's question.
PREFIX core:    <https://w3id.org/examplebank/platform/core#>
PREFIX ingress: <https://w3id.org/examplebank/platform/ingress#>
PREFIX cp:      <https://w3id.org/examplebank/platform/control-plane#>

SELECT ?principal ?tenant ?application ?hostname ?pathPrefix ?scope WHERE {

    # the subject may act for the tenant
    ?membership cp:memberPrincipal ?principal ;
                cp:memberOfTenant ?tenant ;
                cp:hasMembershipState cp:memberstate-active .

    # the endpoint resolves to that tenant and serves this application
    ?endpoint ingress:boundToTenant ?tenant ;
              ingress:servesApplication ?application ;
              ingress:hostname ?hostname .
    OPTIONAL { ?endpoint ingress:pathPrefix ?pathPrefix }

    # the tenant owns the application
    ?application core:ownedBy ?tenant .

    # and it is enabled in a scope covering the endpoint's binding scope
    ?enablement a cp:ApplicationEnablement ;
                cp:forApplication ?application ;
                cp:declarationScope ?scope .
    ?binding cp:declaresRouteBinding ?endpoint ;
             cp:declarationScope ?bindingScope .
    ?bindingScope cp:subScopeOf* ?scope .

    # every confirmed capability requirement is covered by an active
    # subscription and by an offering reaching that scope
    FILTER NOT EXISTS {
        ?requirement cp:ofApplication ?application ;
                     cp:requiredCapability ?capability ;
                     cp:hasApproval ?confirmed .
        FILTER NOT EXISTS {
            ?subscription cp:subscriber ?tenant ;
                          cp:subscribedCapability ?capability ;
                          cp:hasSubscriptionState cp:substate-active .
            ?offering cp:offersCapability ?capability ;
                      cp:offeredInScope ?offeringScope .
            ?scope cp:subScopeOf* ?offeringScope .
        }
    }
}

# CQ-9 — Which commitments does each offering carry, with metric, target, source
# and validation, and what is the latest observation of each? A committed
# commitment with no source or no validation is a violation before this runs.
PREFIX cmt:  <https://w3id.org/examplebank/platform/commitment#>
PREFIX cp:   <https://w3id.org/examplebank/platform/control-plane#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT ?offering ?commitment ?scope ?approver ?metric ?comparator ?target ?unit ?window ?source ?validation ?latestResult WHERE {
  ?commitment a cmt:Commitment ;
      cmt:commitsTo ?offering ; cmt:metric ?m ; cmt:target ?target ; cmt:unit ?unit ;
      cmt:comparator ?cmp ; cmt:window ?window ; cmt:measuredBy ?source ; cmt:validatedBy ?validation .
  ?m skos:notation ?metric . ?cmp skos:notation ?comparator .
  OPTIONAL { ?commitment cp:declarationScope ?scope }
  OPTIONAL { ?commitment cp:hasApproval ?a . ?a cp:approvedBy ?approver }
  OPTIONAL {
    ?obs cmt:observationOf ?commitment ; sosa:hasSimpleResult ?latestResult ; cp:windowEnd ?end .
    FILTER NOT EXISTS { ?obs2 cmt:observationOf ?commitment ; cp:windowEnd ?end2 . FILTER(?end2 > ?end) }
  }
}
ORDER BY ?offering ?commitment
